    /// Open the Document JSON dialog pre-filled with the current document, serialized with
    /// the same JSON codec the web build saves with (`storage::to_json_bytes`). The text is
    /// meant to travel through a bug report: copy it out to attach a document state, or
    /// paste a reported state in and load it.
    fn open_json_dialog(&mut self) {
        match crate::storage::to_json_bytes(&self.state.doc) {
            Ok(bytes) => {
                self.json_dialog = Some(String::from_utf8_lossy(&bytes).into_owned());
            }
            Err(e) => self.state.status = format!("Could not serialize document: {e}"),
        }
    }

    /// Per-frame UI for the Document JSON dialog (see [`Self::open_json_dialog`]).
    fn show_json_dialog(&mut self, ctx: &egui::Context) {
        let Some(text) = self.json_dialog.as_mut() else {
            return;
        };
        let mut open = true;
        let mut copy = false;
        let mut load = false;
        let mut refresh = false;
        egui::Window::new("Document JSON")
            .open(&mut open)
            .resizable(true)
            .default_width(560.0)
            .show(ctx, |ui| {
                ui.label(
                    "The whole document as JSON. Copy it into a bug report — or paste a \
                     reported document here and load it.",
                );
                ui.horizontal(|ui| {
                    copy = ui.button("Copy to clipboard").clicked();
                    refresh = ui.button("Refresh from document").clicked();
                    load = ui.button("Load into document").clicked();
                });
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    ui.add(
                        egui::TextEdit::multiline(text)
                            .code_editor()
                            .desired_width(f32::INFINITY)
                            .desired_rows(20),
                    );
                });
            });
        if copy {
            ctx.copy_text(text.clone());
            self.state.status = "Document JSON copied to clipboard".to_string();
        }
        if load {
            let bytes = text.clone().into_bytes();
            self.state.open_document_bytes(&bytes, "pasted JSON");
        }
        if refresh {
            self.open_json_dialog();
        } else if !open {
            self.json_dialog = None;
        }
    }

    /// Export the current document as a deterministic Lua script (File → Export → Lua Script…).
    /// Walks the element graph; no `bearcad.ui` (#1159).
    #[cfg(not(target_arch = "wasm32"))]
    fn export_document_lua(&mut self) {
        let timestamp = command_log::utc_timestamp();
        let script = export_lua::document_to_lua(&self.state.doc);
        let picked = rfd::FileDialog::new()
            .add_filter("Lua script", &["lua"])
            .set_file_name(format!("bearcad-document-{timestamp}.lua"))
            .save_file();
        if let Some(path) = picked {
            match std::fs::write(&path, script) {
                Ok(()) => {
                    self.state.status =
                        format!("Exported document Lua to {}", path.display());
                }
                Err(e) => {
                    self.state.status = format!("Failed to export Lua: {e}");
                }
            }
        }
    }

    /// DEV (#1159): generate Lua for the live document, run it in a temporary document,
    /// and report what differs.
    #[cfg(not(target_arch = "wasm32"))]
    fn verify_lua_export(&mut self) {
        let script = export_lua::document_to_lua(&self.state.doc);
        let mut runner = match ScriptRunner::from_lua_source(&script) {
            Ok(r) => r,
            Err(e) => {
                self.state.status =
                    format!("Verify Lua export: could not load script: {}", e.message);
                eprintln!(
                    "Verify Lua export: could not load script: {}",
                    e.message
                );
                return;
            }
        };
        runner.verbose = false;
        let mut temp = AppState::default();
        // Carry over nothing from the live UI — pure model recreate.
        let mut synthetic = script::SyntheticInput::default();
        let ctx = egui::Context::default();
        let vp = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(960.0, 560.0));
        while !runner.done {
            runner.tick(&mut temp, &mut synthetic, Some(vp), &ctx);
        }
        if let Some(err) = runner.error {
            self.state.status = format!("Verify Lua export: script failed: {err}");
            eprintln!("Verify Lua export: script failed:\n{err}\n--- script ---\n{script}");
            return;
        }
        let diffs = export_lua::document_diff(&self.state.doc, &temp.doc);
        if diffs.is_empty() {
            self.state.status = "Verify Lua export: documents match".to_string();
            eprintln!("Verify Lua export: documents match");
        } else {
            let summary = diffs.join("; ");
            self.state.status = format!("Verify Lua export: mismatch — {summary}");
            eprintln!("Verify Lua export: mismatches:");
            for d in &diffs {
                eprintln!("  - {d}");
            }
            eprintln!("--- script ---\n{script}");
        }
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn open(&mut self) {
        let picked = rfd::FileDialog::new()
            .add_filter("BearCAD document", &["bearcad"])
            .pick_file();
        if let Some(path) = picked {
            let path = path.to_string_lossy().to_string();
            self.state.apply(Action::Open { path });
            self.rebind_active_document();
        }
    }

    /// Apply the results of finished async browser dialogs (web build).
    #[cfg(target_arch = "wasm32")]
    fn drain_web_io(&mut self, ctx: &egui::Context) {
        let events: Vec<WebIoEvent> = self.web_io.borrow_mut().drain(..).collect();
        for event in events {
            match event {
                WebIoEvent::OpenedDocument { name, bytes } => {
                    self.state.open_document_bytes(&bytes, &name);
                }
                WebIoEvent::ImportStl { name, bytes } => {
                    self.state.import_stl_bytes(&name, &bytes);
                }
                WebIoEvent::ImportStep { name, bytes } => {
                    self.state.import_step_bytes(&name, &bytes);
                }
                WebIoEvent::ImportImage { name, bytes, plane } => {
                    self.state.import_image_bytes(&name, bytes, plane);
                }
                WebIoEvent::RunScript { bytes } => {
                    self.run_web_script(ctx, &bytes);
                }
                WebIoEvent::ImportLua { bytes } => {
                    if !export_lua::document_is_blank(&self.state.doc) {
                        self.pending_import_lua_bytes = Some(bytes);
                    } else {
                        self.run_web_script(ctx, &bytes);
                        self.state.status = "Imported Lua script".to_string();
                    }
                }
                WebIoEvent::Status(message) => self.state.status = message,
            }
        }
    }

    /// Run a picked `.lua` script's bytes through the Lua interpreter module against the live
    /// document, then report the outcome in the status line.
    #[cfg(target_arch = "wasm32")]
    fn run_web_script(&mut self, ctx: &egui::Context, bytes: &[u8]) {
        let src = match std::str::from_utf8(bytes) {
            Ok(s) => s,
            Err(_) => {
                self.state.status = "Script isn't valid UTF-8 text".to_string();
                return;
            }
        };
        self.state.status = match web_lua::run_script(
            &mut self.state,
            &mut self.synthetic,
            self.last_viewport,
            ctx,
            src,
        ) {
            Ok(()) => "Script complete".to_string(),
            Err(err) => format!("Script error: {err}"),
        };
    }

    /// Fetch `url` and queue its bytes as an opened document (`?open=<url>`): how a docs
    /// page links straight into a live model. A fetch that fails lands as a status line
    /// instead of a document.
    #[cfg(target_arch = "wasm32")]
    fn queue_web_open_url(&self, url: String) {
        let queue = self.web_io.clone();
        wasm_bindgen_futures::spawn_local(async move {
            let fetched: Result<Vec<u8>, String> = async {
                let window = web_sys::window().ok_or("no window")?;
                let resp = wasm_bindgen_futures::JsFuture::from(window.fetch_with_str(&url))
                    .await
                    .map_err(|e| format!("{e:?}"))?;
                let resp: web_sys::Response =
                    resp.dyn_into().map_err(|_| "not a response".to_string())?;
                if !resp.ok() {
                    return Err(format!("HTTP {}", resp.status()));
                }
                let buf = wasm_bindgen_futures::JsFuture::from(
                    resp.array_buffer().map_err(|e| format!("{e:?}"))?,
                )
                .await
                .map_err(|e| format!("{e:?}"))?;
                Ok(js_sys::Uint8Array::new(&buf).to_vec())
            }
            .await;
            let name = url
                .rsplit('/')
                .next()
                .filter(|n| !n.is_empty())
                .unwrap_or("document")
                .to_string();
            queue.borrow_mut().push(match fetched {
                Ok(bytes) => WebIoEvent::OpenedDocument { name, bytes },
                Err(e) => WebIoEvent::Status(format!("Open failed for {url}: {e}")),
            });
        });
    }

    /// Browser open dialog → queue the picked file's bytes as `make_event`'s event.
    #[cfg(target_arch = "wasm32")]
    fn web_pick_file(
        &self,
        filter_name: &'static str,
        extensions: &'static [&'static str],
        make_event: impl Fn(String, Vec<u8>) -> WebIoEvent + 'static,
    ) {
        let queue = self.web_io.clone();
        wasm_bindgen_futures::spawn_local(async move {
            if let Some(file) = rfd::AsyncFileDialog::new()
                .add_filter(filter_name, extensions)
                .pick_file()
                .await
            {
                let name = file.file_name();
                let bytes = file.read().await;
                queue.borrow_mut().push(make_event(name, bytes));
            }
        });
    }

    /// Browser save dialog → write `bytes` (the browser downloads the file).
    #[cfg(target_arch = "wasm32")]
    fn web_save_bytes(
        &self,
        filter_name: &'static str,
        extensions: &'static [&'static str],
        suggested_name: String,
        bytes: Vec<u8>,
        done_status: String,
    ) {
        let queue = self.web_io.clone();
        wasm_bindgen_futures::spawn_local(async move {
            if let Some(handle) = rfd::AsyncFileDialog::new()
                .add_filter(filter_name, extensions)
                .set_file_name(&suggested_name)
                .save_file()
                .await
            {
                let message = match handle.write(&bytes).await {
                    Ok(()) => done_status,
                    Err(e) => format!("Save failed: {e}"),
                };
                queue.borrow_mut().push(WebIoEvent::Status(message));
            }
        });
    }

    /// Web File-menu implementations: same names the shared menu dispatch calls, backed by
    /// browser dialogs and the byte-level document/import/export helpers (no filesystem).
    #[cfg(target_arch = "wasm32")]
    fn open(&mut self) {
        self.web_pick_file("BearCAD document", &["bearcad", "json"], |name, bytes| {
            WebIoEvent::OpenedDocument { name, bytes }
        });
    }

