    /// #1149/#1153/#1167: body-face strokes are dark outside sketch mode (contrast on light
    /// fills) and bright while a sketch is open (bodies dim in sketch mode).
    #[test]
    fn body_face_sketch_stroke_colors_cover_sketch_and_view() {
        assert_eq!(col::RECT_LINE_ON_BODY, Color32::from_rgb(50, 60, 78));
        assert_eq!(col::RECT_LINE_ON_BODY_IN_SKETCH, Color32::from_rgb(170, 190, 225));
        assert_ne!(col::RECT_LINE_ON_BODY, col::RECT_LINE);
        assert_ne!(col::RECT_LINE_ON_BODY, col::RECT_LINE_ON_BODY_IN_SKETCH);
        // Dark on-body: blue-grey, dark enough for light body fills.
        assert!(col::RECT_LINE_ON_BODY.b() > col::RECT_LINE_ON_BODY.g());
        assert!(col::RECT_LINE_ON_BODY.g() > col::RECT_LINE_ON_BODY.r());
        assert!(col::RECT_LINE_ON_BODY.b() < 100);
        // In-sketch on-body: brighter than the dark stroke so it reads on dimmed bodies.
        let dark = col::RECT_LINE_ON_BODY;
        let bright = col::RECT_LINE_ON_BODY_IN_SKETCH;
        assert!(bright.r() > dark.r() && bright.g() > dark.g() && bright.b() > dark.b());
        assert!(bright.b() > bright.g() && bright.g() > bright.r());
    }

    /// #262: the revolve arc handle sits at `angle` around the axis, and a cursor at that
    /// handle's screen position reads back the same angle (dragging around the arc sets it).
    #[test]
    fn revolve_arc_angle_round_trips_through_the_cursor() {
        let center = Vec3::ZERO;
        let axis = Vec3::Z;
        let zero_dir = Vec3::X;
        let radius = 10.0;
        // Identity-ish projection: world (x, y) → screen (x, y).
        let project = |w: Vec3| Some(Pos2::new(w.x, w.y));
        let zero_world = center + zero_dir * radius;
        let sign_probe = revolve_arc_handle_world(center, axis, zero_dir, radius, 5.0);

        for target in [30.0_f32, 90.0, 200.0, 270.0, 359.0] {
            let handle = revolve_arc_handle_world(center, axis, zero_dir, radius, target);
            let cursor = project(handle).unwrap();
            let got =
                revolve_arc_angle_from_cursor(cursor, center, zero_world, sign_probe, &project)
                    .unwrap();
            assert!(
                (got - target).abs() < 0.5,
                "angle {target} round-trips, got {got}"
            );
        }
    }

    /// #218: the body tools resolve a whole body from any of its sub-elements — an edge, a
    /// vertex, or a face — so clicking anywhere on a body selects it. (Previously they matched
    /// `scene_element_from_pick(..) == Body`, which is unreachable, so no body could be picked.)
    #[test]
    fn body_index_from_pick_reads_every_body_sub_element() {
        use crate::construction::PickTargetKind;
        use super::body_index_from_pick;
        assert_eq!(
            body_index_from_pick(&PickTargetKind::BodyVertex { body: bkey(3), position: Vec3::ZERO }),
            Some(bkey(3))
        );
        assert_eq!(
            body_index_from_pick(&PickTargetKind::BodyEdge { body: bkey(5), a: Vec3::ZERO, b: Vec3::X }),
            Some(bkey(5))
        );
        assert_eq!(
            body_index_from_pick(&PickTargetKind::BodyFace {
                body: bkey(2),
                triangles: vec![],
                normal: Vec3::Z,
            }),
            Some(bkey(2))
        );
        assert_eq!(body_index_from_pick(&PickTargetKind::Line(lkey(0))), None);
        assert_eq!(body_index_from_pick(&PickTargetKind::ConstructionPlane(pkey(0))), None);
    }

    /// #932: the anchor a shape lands on is whichever candidate the cursor is really
    /// pointing at — the nearest to the eye — not whichever kind of face was looked up
    /// first. A construction plane behind a body used to win over the body's own face.
    #[test]
    fn nearest_anchor_prefers_what_is_in_front() {
        use super::nearest_anchor;
        let eye = Vec3::new(0.0, 0.0, 100.0);
        let near = (Vec3::new(0.0, 0.0, 40.0), Vec3::Z, Vec3::X);
        let far = (Vec3::new(0.0, 0.0, -10.0), Vec3::Y, Vec3::X);
        assert_eq!(nearest_anchor(eye, Some(far), Some(near)), Some(near));
        assert_eq!(nearest_anchor(eye, Some(near), Some(far)), Some(near));
        assert_eq!(nearest_anchor(eye, None, Some(far)), Some(far));
        assert_eq!(nearest_anchor(eye, Some(near), None), Some(near));
        assert_eq!(nearest_anchor(eye, None, None), None);
    }

    /// #902: with the Select tool a click on a body's flat face selects the **whole body** —
    /// bodies outrank faces — while an edge or a corner still outranks the body.
    #[test]
    fn select_tool_picks_the_body_for_a_face_but_not_for_an_edge() {
        use super::select_tool_element_from_pick;
        use crate::construction::PickTargetKind;
        assert_eq!(
            select_tool_element_from_pick(&PickTargetKind::BodyFace {
                body: bkey(2),
                triangles: vec![],
                normal: Vec3::Z,
            }),
            Some(SceneElement::Body(bkey(2)))
        );
        assert!(matches!(
            select_tool_element_from_pick(&PickTargetKind::BodyEdge {
                body: bkey(2),
                a: Vec3::ZERO,
                b: Vec3::X,
            }),
            Some(SceneElement::BodyEdge { body, .. }) if body == bkey(2)
        ));
        assert!(matches!(
            select_tool_element_from_pick(&PickTargetKind::BodyVertex {
                body: bkey(2),
                position: Vec3::ZERO,
            }),
            Some(SceneElement::BodyVertex { body, .. }) if body == bkey(2)
        ));
        // The exploder's own body leaf resolves the same way.
        assert_eq!(
            select_tool_element_from_pick(&PickTargetKind::Body(bkey(7))),
            Some(SceneElement::Body(bkey(7)))
        );
        // Sketch geometry is untouched.
        assert_eq!(
            select_tool_element_from_pick(&PickTargetKind::Line(lkey(3))),
            Some(SceneElement::Line(lkey(3)))
        );
    }

