    /// #125: an uncaught script error under `--exit` must close (so CI doesn't hang) and
    /// fail the process (so CI doesn't silently pass a broken script).
    #[test]
    fn script_error_with_exit_flag_closes_and_fails_the_process() {
        let action = script_finished_close_action(true, false, true);
        assert!(action.close, "must close so the process isn't left hanging");
        assert!(action.fail_process, "must fail so CI catches the broken script");
    }

    /// Without `--exit`, an error leaves the app open for interactive inspection — only the
    /// `--timeout` watchdog (a separate mechanism) should ever force it closed.
    #[test]
    fn script_error_without_exit_flag_stays_open() {
        let action = script_finished_close_action(true, false, false);
        assert!(!action.close);
        assert!(!action.fail_process);
    }

    /// `bearcad.quit()` always closes the window, whether or not `--exit` was passed — but
    /// a clean quit (no error) must never fail the process.
    #[test]
    fn explicit_quit_closes_without_failing_the_process() {
        for exit_flag in [false, true] {
            let action = script_finished_close_action(false, true, exit_flag);
            assert!(action.close);
            assert!(!action.fail_process);
        }
    }

    /// A script that finishes cleanly only closes if `--exit` was requested; either way it
    /// never fails the process.
    #[test]
    fn clean_completion_closes_only_when_exit_flag_is_set() {
        let stays_open = script_finished_close_action(false, false, false);
        assert!(!stays_open.close);
        assert!(!stays_open.fail_process);

        let closes = script_finished_close_action(false, false, true);
        assert!(closes.close);
        assert!(!closes.fail_process);
    }

    #[test]
    fn extrude_preview_uses_pending_target_before_commit() {
        // While dragging the gizmo, the snapped target lives in `pending_extrude_target`
        // (only copied onto `creating_extrusion.target` at commit time) — the ghost preview
        // must still pick it up live so it shows the real (e.g. slanted) shape while
        // dragging, not just after release (#63).
        use crate::actions::{Action, AppState, Tool};
        use crate::model::{ExtrudeFace, ExtrudeTarget};

        let mut state = AppState::default();
        state.apply(Action::BeginSketch {
            face: crate::model::FaceId::ConstructionPlane(pkey(0)),
            viewport: None,
        });
        let sketch = state.sketch_session.unwrap().sketch;
        crate::construction::add_line_rectangle(&mut state.doc, sketch, 0.0, 0.0, 10.0, 5.0, [false; 4]);
        state.apply(Action::SetTool(Tool::Extrude));
        state.apply(Action::ToggleExtrudeFace {
            face: ExtrudeFace::Polygon(vec![lkey(0), lkey(1), lkey(2), lkey(3)]),
        });
        let ce = state.creating_extrusion.as_ref().unwrap();
        assert_eq!(ce.target, None, "target isn't committed onto ce yet");

        let cam = state.cam.clone();
        let element_visibility = state.element_visibility.clone();
        let selection = state.scene_selection.clone();
        let health = state.document_health.clone();
        let pending = Some(ExtrudeTarget::Plane(pkey(0)));

        let scene_input = build_viewport_scene_input(
            &state.doc,
            &cam,
            test_viewport_rect(),
            None,
            &element_visibility,
            &selection,
            &health,
            None,
            None,
            None,
            None,
            state.creating_extrusion.as_ref(),
            None,
            None,
            None,
            Vec::new(),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            pending.clone(),
            None,
            None,
            None,
            Vec::new(),
            Vec::new(),
            None,
            None,
            None,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            &[],
            None,
            None,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            std::collections::HashMap::new(),
        );
        assert_eq!(
            scene_input.preview_extrusion.as_ref().map(|e| e.target.clone()),
            Some(pending),
            "ghost preview should pick up the live pending target before commit"
        );
    }

    /// #223: while the Repeat tool holds picked bodies and an evaluable count, the scene carries a
    /// ghost mesh per would-be instance (count − 1 copies of each target).
    #[test]
    fn repeat_tool_ghosts_the_would_be_instances() {
        use crate::actions::{Action, AppState, CreatingRepeat, Tool};
        use crate::model::{ExtrudeFace, RepeatMode, RevolveAxis};

        let mut state = AppState::default();
        // Build one real body: a rectangle extruded into a block.
        state.apply(Action::BeginSketch {
            face: crate::model::FaceId::ConstructionPlane(pkey(0)),
            viewport: None,
        });
        let sketch = state.sketch_session.unwrap().sketch;
        crate::construction::add_line_rectangle(&mut state.doc, sketch, 0.0, 0.0, 10.0, 5.0, [false; 4]);
        state.apply(Action::SetTool(Tool::Extrude));
        state.apply(Action::ToggleExtrudeFace {
            face: ExtrudeFace::Polygon(vec![lkey(0), lkey(1), lkey(2), lkey(3)]),
        });
        state.apply(Action::CommitExtrusion);
        assert!(state.doc.bodies.len() > 0, "an extruded body exists");

        state.tool = Tool::Repeat;
        state.creating_repeat = Some(CreatingRepeat {
            targets: vec![bkey(0)],
            axis: Some(RevolveAxis::X),
            mode: RepeatMode::CountGap,
            count: "3".to_string(),
            spacing: "10".to_string(),
            ..CreatingRepeat::default()
        });

        let cam = state.cam.clone();
        let element_visibility = state.element_visibility.clone();
        let selection = state.scene_selection.clone();
        let health = state.document_health.clone();

        let scene_input = build_viewport_scene_input(
            &state.doc,
            &cam,
            test_viewport_rect(),
            None,
            &element_visibility,
            &selection,
            &health,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            Vec::new(),
            None,
            state.creating_repeat.as_ref(),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            Vec::new(),
            Vec::new(),
            None,
            None,
            None,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            &[],
            None,
            None,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            std::collections::HashMap::new(),
        );
        // 3 instances = original + 2 ghosts; each ghost is a non-empty translated copy.
        assert_eq!(scene_input.repeat_ghosts.len(), 2);
        assert!(scene_input.repeat_ghosts.iter().all(|g| !g.is_empty()));

        // #990: a **cut extrusion** replayed at each offset previews too. It produces no output
        // body, so the body-target loop never saw it and picking one to repeat showed nothing
        // at all until commit — the ghost is the extrusion's own prism, the tool that carves
        // the hole, parked where each extra hole will be punched.
        let cut = state.doc.extrusions.insert(crate::model::Extrusion {
            sketch,
            faces: vec![ExtrudeFace::Polygon(vec![lkey(0), lkey(1), lkey(2), lkey(3)])],
            distance: -3.0,
            target: None,
            expression: String::new(),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        state.creating_repeat = Some(CreatingRepeat {
            // No bodies at all: the cut alone is what is being repeated.
            targets: Vec::new(),
            extrusion_targets: vec![cut],
            axis: Some(RevolveAxis::X),
            mode: RepeatMode::CountGap,
            count: "3".to_string(),
            spacing: "10".to_string(),
            ..CreatingRepeat::default()
        });
        let scene_input = build_viewport_scene_input(
            &state.doc,
            &cam,
            test_viewport_rect(),
            None,
            &element_visibility,
            &selection,
            &health,
            None, None, None, None, None, None, None, None,
            Vec::new(),
            None,
            state.creating_repeat.as_ref(),
            None, None, None, None, None, None, None, None, None,
            Vec::new(),
            Vec::new(),
            None, None, None,
            Vec::new(), Vec::new(), Vec::new(), Vec::new(), Vec::new(),
            Vec::new(),
            &[],
            None, None,
            Vec::new(), Vec::new(), Vec::new(), Vec::new(),
            std::collections::HashMap::new(),
        );
        assert_eq!(
            scene_input.repeat_ghosts.len(),
            2,
            "a repeated cut extrusion ghosts its prism at each extra placement"
        );
        assert!(scene_input.repeat_ghosts.iter().all(|g| !g.is_empty()));
    }

    /// #660: an in-progress snap move ghosts each body at its destination, so the translation
    /// previews before commit like the Mirror and Repeat ones do.
    #[test]
    fn move_tool_ghosts_the_snapped_destination() {
        use crate::model::{MovePointRef, MoveTranslateMode};
        let mut state = crate::actions::AppState::default();
        let mesh = state.doc.imported_meshes.insert(crate::model::ImportedMesh {
            triangles: vec![[
                glam::Vec3::ZERO,
                glam::Vec3::new(10.0, 0.0, 0.0),
                glam::Vec3::new(0.0, 10.0, 0.0),
            ]],
            source_name: "tri".to_string(),
                    step_bytes: None,
        });
        state.doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Imported(mesh),
            material: None,
            name: None,
            shadow: false,
        });
        let cam = crate::camera::Camera::default();
        let element_visibility = crate::hierarchy::ElementVisibility::default();
        let selection = crate::selection::SceneSelection::default();
        let health = crate::document_health::DocumentHealth::default();
        let q = crate::hierarchy::quantize_body_point;

        let ghosts = |cm: Option<&actions::CreatingMove>| {
            build_viewport_scene_input(
                &state.doc,
                &cam,
                test_viewport_rect(),
                None,
                &element_visibility,
                &selection,
                &health,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Vec::new(),
                None,
                None,
                None,
                cm,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Vec::new(),
                Vec::new(),
                None,
                None,
                None,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                &[],
                None,
                None,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                std::collections::HashMap::new(),
            )
            .repeat_ghosts
        };

        // Nothing picked yet, or a move that resolves to no motion: no ghost to draw.
        assert_eq!(ghosts(None).len(), 0);
        let picking = actions::CreatingMove {
            targets: vec![bkey(0)],
            translate_mode: MoveTranslateMode::PointSnap,
            start_point_a: Some(MovePointRef::Vertex { body: bkey(0), p: q(glam::Vec3::ZERO) }),
            ..Default::default()
        };
        assert_eq!(ghosts(Some(&picking)).len(), 0, "an identity move has nothing to preview");

        // Both points picked: one ghost, at the destination.
        let snapped = actions::CreatingMove {
            end_point_a: Some(MovePointRef::Vertex {
                            body: bkey(0),
                p: q(glam::Vec3::new(10.0, 0.0, 0.0)),
            }),
            ..picking
        };
        assert_eq!(ghosts(Some(&snapped)).len(), 1, "the snapped destination ghosts");

        // A complete B pair rotates the ghost too (#748): start B (the far corner) swings
        // about end point A onto end B — here a quarter turn about Z, so the corner that
        // rode the translation to (20, 0, 0) previews at (10, 10, 0).
        let rotated = actions::CreatingMove {
            start_point_b: Some(MovePointRef::Vertex {
                body: bkey(0),
                p: q(glam::Vec3::new(10.0, 0.0, 0.0)),
            }),
            end_point_b: Some(MovePointRef::OnEdge {
                body: bkey(0),
                p: q(glam::Vec3::new(10.0, 10.0, 0.0)),
            }),
            start_point_c: None,
            end_point_c: None,
            ..snapped
        };
        let ghost = ghosts(Some(&rotated));
        assert_eq!(ghost.len(), 1);
        let landed = glam::Vec3::new(10.0, 10.0, 0.0);
        assert!(
            ghost[0]
                .triangles
                .iter()
                .flatten()
                .any(|p| (*p - landed).length() < 1e-3),
            "the rotated corner previews at end B, got {:?}",
            ghost[0].triangles
        );
    }

    /// #1017: the Joint tool previews its mate — the driven part ghosted where the face
    /// pair and the line-up rows put it, live as each pick lands.
    #[test]
    fn a_joints_mate_previews_where_the_part_lands() {
        use crate::actions::CreatingJoint;
        use crate::mate::tests::{cube_body, face_ref};
        use crate::model::{JointKind, JointRef};
        let mut doc = crate::model::Document::default();
        let fixed = cube_body(&mut doc, glam::Vec3::ZERO, glam::Vec3::splat(10.0));
        let moving = cube_body(&mut doc, glam::Vec3::new(40.0, 0.0, 0.0), glam::Vec3::splat(4.0));
        let mut cj = CreatingJoint {
            members: vec![JointRef::Body(fixed), JointRef::Body(moving)],
            base: 0,
            kind: JointKind::Slider,
            ..Default::default()
        };
        let probe = |cj: &CreatingJoint| crate::model::Joint {
            members: cj.members.clone(),
            base: cj.base,
            kind: cj.kind.clone(),
            placement: cj.placement.as_op(),
            position: String::new(),
            position2: String::new(),
            position3: String::new(),
            rest: String::new(),
            rest2: String::new(),
            rest3: String::new(),
            limits: Default::default(),
            name: None,
            frame: Default::default(),
        };
        // The mate is a Face Snap move (#1079): each face is held as the point at its middle.
        let point = |body, near| match face_ref(&doc, body, near) {
            model::MateRef::Face { body, centroid, normal } => {
                model::MovePointRef::OnFace { body, centroid, normal, uv: [0, 0] }
            }
            other => panic!("expected a face, got {other:?}"),
        };
        // Half a face pair previews nothing: there is no placement yet.
        cj.placement.translate_mode = model::MoveTranslateMode::FaceSnap;
        cj.placement.start_point_a = Some(point(moving, glam::Vec3::new(42.0, 2.0, 0.0)));
        assert!(
            joints::preview_pose(&doc, &probe(&cj)).is_none(),
            "half a face pair places nothing"
        );
        // Completing it ghosts the part flush on the fixed face.
        cj.placement.end_point_a = Some(point(fixed, glam::Vec3::new(5.0, 5.0, 10.0)));
        let pose = joints::preview_pose(&doc, &probe(&cj)).expect("a complete pair previews");
        // Face Snap lands the moving face's middle **on** the fixed one's (#1079).
        let landed = pose.transform_point3(glam::Vec3::new(42.0, 2.0, 0.0));
        assert!(
            (landed - glam::Vec3::new(5.0, 5.0, 10.0)).length() < 1e-3,
            "the ghost sits on the fixed face, at {landed}"
        );
    }

    /// #668: once both A points are picked, a connector spans them — the translation drawn as
    /// a vector. Either point missing (or no longer resolving) draws nothing.
    #[test]
    fn move_snap_connector_spans_the_a_points() {
        use super::SnapPreviewPoints;
        use crate::model::MovePointRef;
        let q = crate::hierarchy::quantize_body_point;
        let corner = glam::Vec3::new(10.0, 0.0, 0.0);

        let mut doc = crate::model::Document::default();
        let mesh = doc.imported_meshes.insert(crate::model::ImportedMesh {
            triangles: vec![[glam::Vec3::ZERO, corner, glam::Vec3::new(0.0, 10.0, 0.0)]],
            source_name: "tri".to_string(),
                    step_bytes: None,
        });
        doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Imported(mesh),
            material: None,
            name: None,
            shadow: false,
        });

        let start = MovePointRef::Vertex { body: bkey(0), p: q(glam::Vec3::ZERO) };
        let end = MovePointRef::Vertex { body: bkey(0), p: q(corner) };
        let half = SnapPreviewPoints { start_a: Some(start), ..Default::default() };
        assert_eq!(half.connector(&doc), None, "one point isn't a vector");

        let both = SnapPreviewPoints { end_a: Some(end), ..half };
        let (a, b) = both.connector(&doc).expect("both points resolve");
        assert!((a - glam::Vec3::ZERO).length() < 1e-3, "starts at start A, got {a:?}");
        assert!((b - corner).length() < 1e-3, "ends at end A, got {b:?}");

        // A point that no longer resolves draws nothing rather than a wrong line.
        let gone = SnapPreviewPoints {
            end_a: Some(MovePointRef::Vertex { body: bkey(0), p: [9999; 3] }),
            ..both
        };
        assert_eq!(gone.connector(&doc), None);

        // The two marks are visibly different colours — go and stop.
        assert_ne!(crate::theme::MOVE_START_POINT, crate::theme::MOVE_END_POINT);
    }

    /// #180: drawing-view projection axes are orthonormal and orient as expected — a Front
    /// view maps world X→right and Z→up (ignoring depth Y); the isometric basis is a proper
    /// horizontal-right / up frame.
    #[test]
    fn drawing_view_axes_project_as_expected() {
        use crate::model::DrawingOrientation;
        let (r, u) = crate::drawing::view_axes(DrawingOrientation::Front);
        assert_eq!((r, u), (Vec3::X, Vec3::Z));
        let p = Vec3::new(3.0, 99.0, 7.0);
        assert!((p.dot(r) - 3.0).abs() < 1e-6 && (p.dot(u) - 7.0).abs() < 1e-6);

        let (r, u) = crate::drawing::view_axes(DrawingOrientation::Isometric);
        assert!((r.length() - 1.0).abs() < 1e-6, "right is unit");
        assert!((u.length() - 1.0).abs() < 1e-6, "up is unit");
        assert!(r.dot(u).abs() < 1e-6, "right ⟂ up");
        assert!(r.z.abs() < 1e-6, "iso right stays horizontal");
        assert!(u.z > 0.0, "iso up points upward");
    }

    /// #203: while the Loft tool is collecting cross sections, the scene shows a live ghost of
    /// the blended solid, appearing once two sections are picked and dropping back to nothing
    /// with only one.
    #[test]
    fn loft_tool_previews_the_blended_solid_from_picked_sections() {
        use crate::actions::{AppState, CreatingLoft, Tool};
        use crate::model::{Circle, ExtrudeFace, FaceId, LoftSection};

        let mut state = AppState::default();
        // Two circles on planes 10 mm apart, so the loft blends through real space.
        let s0 = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        state.doc.circles.insert(Circle::from_local_center_radius(s0, 0.0, 0.0, 5.0, 0.0));
        state.doc.construction_planes.insert(crate::construction::plane_from_definition(
            &crate::construction::definition_from_reference(
                &crate::construction::PlaneReference::Face {
                    origin: glam::Vec3::ZERO,
                    normal: glam::Vec3::Z,
                    label: "Ground".to_string(),
                },
                10.0,
                0.0,
            ),
            crate::model::ConstructionPlaneParent::Root,
        ));
        let s1 = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(1)));
        state.doc.circles.insert(Circle::from_local_center_radius(s1, 0.0, 0.0, 3.0, 0.0));
        state.tool = Tool::Loft;

        let cam = state.cam.clone();
        let element_visibility = state.element_visibility.clone();
        let selection = state.scene_selection.clone();
        let health = state.document_health.clone();

        let build = |state: &AppState| {
            build_viewport_scene_input(
                &state.doc,
                &cam,
                test_viewport_rect(),
                None,
                &element_visibility,
                &selection,
                &health,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Vec::new(),
                state.creating_loft.as_ref(),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                Vec::new(),
                Vec::new(),
                None,
                None,
                None,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                &[],
                None,
                None,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                std::collections::HashMap::new(),
            )
            .preview_solid
            .is_some()
        };

        // One section: nothing to blend yet, no preview.
        state.creating_loft = Some(CreatingLoft {
            sections: vec![LoftSection { sketch: s0, face: ExtrudeFace::Circle(rkey(0)) }],
            ..CreatingLoft::default()
        });
        assert!(!build(&state), "a single section shouldn't preview a loft");

        // Two sections: the blended solid previews.
        state.creating_loft = Some(CreatingLoft {
            sections: vec![
                LoftSection { sketch: s0, face: ExtrudeFace::Circle(rkey(0)) },
                LoftSection { sketch: s1, face: ExtrudeFace::Circle(rkey(1)) },
            ],
            ..CreatingLoft::default()
        });
        assert!(build(&state), "two sections should preview the blended solid");
    }

