    /// #656: the Move tool steps through its pickers on its own — bodies, then the source
    /// point, then the target point when snapping — so picking one thing arms the next. A
    /// picker focused by hand wins until it's satisfied (#658).
    #[test]
    fn a_destructive_pickers_bodies_read_red_the_rest_blue() {
        // #961: the viewport asks each picker for its colour instead of a per-tool match
        // listing which sets to fold and which bodies to paint red.
        use crate::context::{PickerTarget, ToolPickerView};
        use crate::element_picker::{ElementFilter, ElementKind, ElementPicker, PickLimit};
        let doc = model::Document::default();
        let body_picker = |color: Option<egui::Color32>, bodies: &[crate::model::BodyKey]| {
            let mut p =
                ElementPicker::new(ElementFilter::kind(ElementKind::Body), PickLimit::Infinite);
            if let Some(c) = color {
                p = p.with_selected_color(c);
            }
            // A plain filter with no `LiveBody` rule, so the test needs no real bodies.
            p.set_picked(&doc, bodies.iter().map(|&b| SceneElement::Body(b)));
            ToolPickerView {
                heading: "set",
                picker: p,
                target: PickerTarget::SliceTargets,
                separator_above: true,
                render: context::PickerRender::Shared,
            }
        };
        let kept = body_picker(None, &[bkey(1), bkey(2)]);
        let consumed = body_picker(Some(crate::theme::CUT_ACCENT), &[bkey(3)]);
        let (folded, cut, coloured) = picker_highlights(&[kept, consumed]);
        assert_eq!(folded, vec![SceneElement::Body(bkey(1)), SceneElement::Body(bkey(2))]);
        assert_eq!(cut, vec![bkey(3)], "a consumed body reads red, not blue");

        // No pickers at all — nothing to highlight, and nothing to special-case.
        assert!(
            coloured.is_empty(),
            "a destructive picker's *bodies* take the fill path, not the element one"
        );

        let (folded, cut, coloured) = picker_highlights(&[]);
        assert!(folded.is_empty() && cut.is_empty() && coloured.is_empty());
    }

    #[test]
    fn a_destructive_pickers_faces_read_red_through_the_element_channel() {
        // #961: Slice's cutters include planes and faces (and lines, #1126). A solid takes a
        // fill, but a face has none to recolour, so those go down the coloured-element path
        // instead of being folded into the blue selection — which is what they used to do.
        use crate::context::{PickerTarget, ToolPickerView};
        use crate::element_picker::{ElementFilter, ElementKind, ElementPicker, PickLimit};
        let doc = model::Document::default();
        let mut cutters = ElementPicker::new(
            ElementFilter::kinds(&[ElementKind::Plane, ElementKind::Face]),
            PickLimit::Infinite,
        )
        .with_selected_color(crate::theme::CUT_ACCENT);
        cutters.set_picked(&doc, [SceneElement::ConstructionPlane(pkey(1))]);
        let view = ToolPickerView {
            heading: "Cutters",
            picker: cutters,
            target: PickerTarget::SliceCutters,
            separator_above: true,
            render: context::PickerRender::Shared,
        };
        let (folded, cut_bodies, coloured) = picker_highlights(&[view]);
        assert!(folded.is_empty(), "a cutter is not part of the blue selection");
        assert!(cut_bodies.is_empty(), "it is not a body either");
        assert_eq!(
            coloured,
            vec![(SceneElement::ConstructionPlane(pkey(1)), crate::theme::CUT_ACCENT)],
            "it reads in the picker's red"
        );
    }

    #[test]
    fn a_focus_chain_walks_to_the_first_unfilled_picker() {
        // The generic walk behind both the Move and Joint chains (#954/#962): a single-pick
        // picker hands focus on the moment it's filled.
        use super::{focus_chain_satisfied, focus_chain_step};
        let chain = vec![("primary", true), ("second", false), ("third", false)];
        assert_eq!(focus_chain_step(&chain, None, "primary"), "second");
        // A hand-picked focus pins the chain regardless of what's filled.
        assert_eq!(focus_chain_step(&chain, Some("third"), "primary"), "third");
        // Everything filled falls back to the primary picker.
        let full = vec![("primary", true), ("second", true)];
        assert_eq!(focus_chain_step(&full, None, "primary"), "primary");

        // A hand-picked focus is released once its picker is filled...
        assert!(focus_chain_satisfied(&full, "second"));
        assert!(!focus_chain_satisfied(&chain, "second"));
        // ...except on the primary, where focusing by hand means "I want to add more".
        assert!(
            !focus_chain_satisfied(&full, "primary"),
            "the primary picker is never auto-released"
        );
    }

    #[test]
    fn the_joint_focus_chain_matches_the_move_one() {
        // Both tools run the same walk (#954), so the Joint chain steps like Move's — now
        // through the placement, which *is* a move (#1079): the parts, then the two faces.
        use super::{joint_focus_for, joint_focus_satisfied};
        use crate::mate::tests::{cube_body, face_ref};
        let mut doc = crate::model::Document::default();
        let fixed = cube_body(&mut doc, glam::Vec3::ZERO, glam::Vec3::splat(10.0));
        let moving = cube_body(&mut doc, glam::Vec3::new(40.0, 0.0, 0.0), glam::Vec3::splat(4.0));
        let point = |body, near| match face_ref(&doc, body, near) {
            model::MateRef::Face { body, centroid, normal } => {
                model::MovePointRef::OnFace { body, centroid, normal, uv: [0, 0] }
            }
            other => panic!("expected a face, got {other:?}"),
        };
        let focus = |cj: &actions::CreatingJoint| joint_focus_for(Some(cj), None);
        assert_eq!(joint_focus_for(None, None), JointFocus::Members);

        let mut cj = actions::CreatingJoint::default();
        assert_eq!(focus(&cj), JointFocus::Members, "no parts picked yet");
        cj.members.push(crate::model::JointRef::Body(fixed));
        assert_eq!(focus(&cj), JointFocus::Members, "a joint takes two parts");
        cj.members.push(crate::model::JointRef::Body(moving));
        assert_eq!(focus(&cj), JointFocus::MovingFace);
        cj.placement.start_point_a = Some(point(moving, glam::Vec3::new(42.0, 2.0, 0.0)));
        assert_eq!(focus(&cj), JointFocus::FixedFace);
        cj.placement.end_point_a = Some(point(fixed, glam::Vec3::new(5.0, 5.0, 10.0)));
        // A Face Snap placement names a plane, so it seeds the frame's axis and there is
        // nothing left to ask (#1079).
        assert_eq!(focus(&cj), JointFocus::Members, "the placement is complete");

        // A placement that names no plane leaves the axis unset, so the chain walks into it
        // rather than leaving the joint with nothing to move about.
        let mut free = actions::CreatingJoint {
            members: cj.members.clone(),
            ..Default::default()
        };
        free.placement.translate_mode = model::MoveTranslateMode::InPlace;
        assert_eq!(focus(&free), JointFocus::MovingFace);
        free.placement.translate_mode = model::MoveTranslateMode::Free;
        free.placement.tx = "10".to_string();
        assert_eq!(focus(&free), JointFocus::MovingFace);

        // The slide stops sit outside the chain — hand-focused from the pane, never stepped
        // into — so they're satisfied by their own targets, not by chain position.
        assert!(!joint_focus_satisfied(&doc, &cj, JointFocus::SlideMinStop));
        assert!(
            joint_focus_satisfied(&doc, &cj, JointFocus::FixedFace),
            "a filled pair releases its hand-picked focus"
        );
        assert!(
            !joint_focus_satisfied(&doc, &cj, JointFocus::Members),
            "the primary picker is never auto-released"
        );
    }

    #[test]
    fn move_focus_steps_through_its_pickers() {
        use super::{move_focus_for, move_focus_satisfied};
        use crate::model::{MovePointRef, MoveTranslateMode};
        let point = |body| MovePointRef::Vertex { body, p: [0; 3] };
        let focus = |cm: &actions::CreatingMove| move_focus_for(Some(cm), None);
        assert_eq!(move_focus_for(None, None), MoveFocus::Bodies, "no move in progress");

        let mut cm = actions::CreatingMove {
            translate_mode: MoveTranslateMode::PointSnap,
            ..Default::default()
        };
        assert_eq!(focus(&cm), MoveFocus::Bodies, "no bodies picked yet");

        cm.targets.push(bkey(0));
        assert_eq!(focus(&cm), MoveFocus::StartPointA, "a body arms the source point");

        cm.start_point_a = Some(point(bkey(0)));
        assert_eq!(focus(&cm), MoveFocus::EndPointA);

        cm.end_point_a = Some(point(bkey(1)));
        assert_eq!(
            focus(&cm),
            MoveFocus::StartPointB,
            "the A pair done, the chain walks into start B (#741)"
        );

        // Picking start B opts into the rotation, and end B is then what's missing (#669).
        cm.start_point_b = Some(point(bkey(0)));
        assert_eq!(focus(&cm), MoveFocus::EndPointB);
        cm.end_point_b = Some(point(bkey(1)));
        assert_eq!(
            focus(&cm),
            MoveFocus::StartPointC,
            "the B pair done, the chain walks into start C"
        );

        // C pins the spin about `end A → end B` that B leaves free.
        cm.start_point_c = Some(point(bkey(0)));
        assert_eq!(focus(&cm), MoveFocus::EndPointC);
        cm.end_point_c = Some(point(bkey(1)));
        assert_eq!(focus(&cm), MoveFocus::Bodies, "everything picked");

        // Free translate has no target point to pick.
        let mut free = actions::CreatingMove {
            targets: vec![bkey(0)],
            translate_mode: MoveTranslateMode::Free,
            ..Default::default()
        };
        assert_eq!(focus(&free), MoveFocus::StartPointA);
        free.start_point_a = Some(point(bkey(0)));
        assert_eq!(focus(&free), MoveFocus::Bodies);

        // Face Snap (#1077) needs only the pair, and stops there — the B and C pairs are
        // Point Snap's way of setting a turn; Face Snap's comes from the faces themselves.
        let mut face = actions::CreatingMove {
            targets: vec![bkey(0)],
            translate_mode: MoveTranslateMode::FaceSnap,
            ..Default::default()
        };
        assert_eq!(focus(&face), MoveFocus::StartPointA);
        face.start_point_a = Some(point(bkey(0)));
        assert_eq!(focus(&face), MoveFocus::EndPointA);
        face.end_point_a = Some(point(bkey(1)));
        assert_eq!(focus(&face), MoveFocus::Bodies, "both faces picked, and that is all");

        // A hand-picked focus wins until it's satisfied, then hands the chain back (#658).
        let held = Some(MoveFocus::EndPointA);
        let mut partial = actions::CreatingMove {
            targets: vec![bkey(0)],
            translate_mode: MoveTranslateMode::PointSnap,
            start_point_a: Some(point(bkey(0))),
            ..Default::default()
        };
        assert_eq!(move_focus_for(Some(&partial), held), MoveFocus::EndPointA);
        assert!(!move_focus_satisfied(&partial, MoveFocus::EndPointA), "still unset");
        partial.end_point_a = Some(point(bkey(1)));
        assert!(move_focus_satisfied(&partial, MoveFocus::EndPointA));
        assert_eq!(
            move_focus_for(Some(&partial), None),
            MoveFocus::StartPointB,
            "the chain resumes at start B once the held picker is satisfied (#741)"
        );
    }

    /// #944/#945: a loupe whose own thing has no wireframe near the cursor's hitbox — a whole
    /// body, a big face — would magnify an empty or flat disc, so it zooms out to frame that
    /// thing instead. A thing whose geometry does cross the disc keeps the magnifier.
    #[test]
    fn a_body_loupe_shades_its_faces_back_to_front() {
        // #972: a whole-body loupe should read like the body does in the 3D view — a
        // solid-faced shape — not as a wireframe box of its feature edges.
        let mut doc = model::Document::default();
        let sketch = doc.add_sketch(model::FaceId::ConstructionPlane(pkey(0)));
        let lines =
            construction::add_line_rectangle(&mut doc, sketch, 0.0, 0.0, 100.0, 100.0, [false; 4]);
        doc.extrusions.insert(model::Extrusion {
            sketch,
            faces: vec![model::ExtrudeFace::Polygon(lines.to_vec())],
            distance: 50.0,
            target: None,
            expression: String::new(),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        doc.bodies.insert(model::Body {
            source: model::BodySource::Extrusion(xkey(0)),
            material: None,
            name: None,
            shadow: false,
        });
        // Looking down -Z from high above, so the top cap is nearest the eye.
        let eye = Vec3::new(50.0, 50.0, 500.0);
        let faces = body_loupe_faces(&doc, bkey(0), eye).expect("the body meshes");
        assert!(faces.len() > 4, "a box has more than four triangles");

        // Painter's algorithm: every triangle is at least as far from the eye as the one
        // drawn after it, so nearer faces paint over farther ones. Keyed on the **farthest**
        // vertex, not the centroid (#981) — a big triangle whose centre is far can still have
        // a corner nearer than everything in front of it, and a centroid key would let it
        // paint over them.
        let depth = |tri: &[Vec3; 3]| {
            tri.iter()
                .map(|p| (*p - eye).length())
                .fold(f32::NEG_INFINITY, f32::max)
        };
        for pair in faces.windows(2) {
            assert!(
                depth(&pair[0].0) >= depth(&pair[1].0) - 1e-3,
                "triangles must be ordered far-to-near"
            );
        }

        // Shading varies with the face normal, so the shape reads as solid rather than as a
        // flat wash of one colour.
        let shades: Vec<u8> = faces.iter().map(|(_, shade)| *shade).collect();
        let lo = shades.iter().copied().min().unwrap();
        let hi = shades.iter().copied().max().unwrap();
        assert!(hi > lo, "faces at different angles should shade differently");
    }

    /// #979: a loupe has to show something *of* the thing it stands for. A datum plane drew a
    /// single dot at the pick spot — indistinguishable from a vertex, and saying nothing about
    /// which plane you were pointing at. Guarded by totality, so the next kind added can't
    /// quietly draw nothing either.
    #[test]
    fn every_loupe_has_content_to_magnify() {
        use construction::PickTargetKind as PK;
        let mut doc = model::Document::default();
        let sketch = doc.add_sketch(model::FaceId::ConstructionPlane(pkey(0)));
        let lines =
            construction::add_line_rectangle(&mut doc, sketch, 0.0, 0.0, 10.0, 5.0, [false; 4]);
        doc.circles
            .insert(model::Circle::from_local_center_radius(sketch, 20.0, 20.0, 4.0, 0.0));
        doc.extrusions.insert(model::Extrusion {
            sketch,
            faces: vec![model::ExtrudeFace::Polygon(lines.to_vec())],
            distance: 5.0,
            target: None,
            expression: String::new(),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        doc.bodies.insert(model::Body {
            source: model::BodySource::Extrusion(xkey(0)),
            material: None,
            name: None,
            shadow: false,
        });
        let solid = extrude::body_solid_mesh(&doc, bkey(0)).expect("body mesh");
        let tri = solid.triangles[0];

        for kind in [
            PK::Line(lines[0]),
            PK::Circle(model::circle_key_for_slot(0)),
            PK::Point(model::ConstraintPoint::LineEndpoint {
                line: lines[0],
                end: model::LineEnd::Start,
            }),
            PK::BodyEdge { body: bkey(0), a: tri[0], b: tri[1] },
            PK::BodyVertex { body: bkey(0), position: tri[0] },
            PK::BodyFace {
                body: bkey(0),
                triangles: vec![tri],
                normal: (tri[1] - tri[0]).cross(tri[2] - tri[0]).normalize_or_zero(),
            },
            PK::Body(bkey(0)),
            PK::GlobalAxis(construction::GlobalAxis::X),
            PK::ConstructionPlane(model::plane_key_for_slot(0)),
            PK::SketchFace(model::FaceId::Polygon(lines.to_vec())),
            // The two whose content is a single spot by nature: a point on the ground, and a
            // constraint, whose visual is its badge glyph drawn at the loupe's centre.
            PK::Ground(Vec3::ZERO),
            PK::Constraint(model::constraint_key_for_slot(0)),
        ] {
            let (segments, points) = pick_target_loupe_wireframe(&doc, &kind, Vec3::ZERO);
            assert!(
                !segments.is_empty() || !points.is_empty(),
                "{kind:?} has nothing for its loupe to magnify"
            );
        }

        // The plane's content is its own rectangle, not the pick spot — otherwise the loupe
        // frames itself around nothing.
        let (segments, _) = pick_target_loupe_wireframe(&doc, &PK::ConstructionPlane(model::plane_key_for_slot(0)), Vec3::ZERO);
        assert_eq!(segments.len(), 4, "a plane's four edges");
    }

    /// #979: the world axes draw in **their own** colours in a loupe. Three identically
    /// accented lines in three loupes told you nothing about which was X.
    #[test]
    fn the_axes_keep_their_colours_in_a_loupe() {
        use construction::GlobalAxis;
        let colors: Vec<egui::Color32> = [GlobalAxis::X, GlobalAxis::Y, GlobalAxis::Z]
            .iter()
            .map(|a| a.color())
            .collect();
        let accent = construction::PICK_HOVER_RGBA;
        for color in &colors {
            assert_ne!(*color, accent, "an axis is not the loupe's accent");
        }
        assert_ne!(colors[0], colors[1]);
        assert_ne!(colors[1], colors[2]);
        assert_ne!(colors[0], colors[2]);
    }

    /// #976: a loupe magnifies the scene, so what's in it should wear the colour it wears out
    /// there. Every body's faces were painted in the loupe's own accent instead, so a pink body
    /// showed up blue — the fill was carrying "which loupe is hot", which is the ring's job.
    #[test]
    fn a_loupe_paints_a_body_in_its_own_material() {
        let mut doc = model::Document::default();
        let pink = doc
            .materials
            .insert(model::Material { name: "Pink".to_string(), color: [230, 120, 170] });
        doc.bodies.insert(model::Body {
            source: model::BodySource::Extrusion(xkey(0)),
            material: Some(pink),
            name: None,
            shadow: false,
        });
        // Unshaded, the fill is the material itself.
        let full = loupe_solid_fill(&doc, bkey(0), 1.0, LoupeState::Idle);
        assert_eq!((full.r(), full.g(), full.b()), (230, 120, 170));
        // Shading dims it without tinting it — the hue is still the body's.
        let dim = loupe_solid_fill(&doc, bkey(0), 0.5, LoupeState::Idle);
        assert!(dim.r() > dim.b() && dim.b() > dim.g(), "still pink: {dim:?}");
        assert!(dim.r() < full.r(), "and darker");
        // A body with no material of its own keeps the document's default look, not the accent.
        doc.bodies.insert(model::Body {
            source: model::BodySource::Extrusion(xkey(0)),
            material: None,
            name: None,
            shadow: false,
        });
        assert_ne!(loupe_solid_fill(&doc, bkey(1), 1.0, LoupeState::Idle), full);

        // #980: and it changes with the loupe's state, the way a body's fill does in the 3D
        // view — otherwise a hovered loupe looks exactly like a cold one, since the fill is
        // the whole visual for a body.
        let hovered = loupe_solid_fill(&doc, bkey(0), 1.0, LoupeState::Hovered);
        let selected = loupe_solid_fill(&doc, bkey(0), 1.0, LoupeState::Selected);
        assert_ne!(hovered, full, "a hovered loupe must read differently");
        assert_ne!(selected, full, "so must one holding something selected");
        assert_ne!(hovered, selected);
        assert_eq!(hovered, gpu_viewport::SOLID_FILL_HOVERED, "the 3D view's own hover fill");
        assert_eq!(selected, gpu_viewport::SOLID_FILL_SELECTED);
    }

    #[test]
    fn a_loupe_frames_content_the_magnifier_would_miss() {
        use construction::PickTargetKind as PK;
        let mut doc = model::Document::default();
        let sketch = doc.add_sketch(model::FaceId::ConstructionPlane(pkey(0)));
        let lines = construction::add_line_rectangle(&mut doc, sketch, 0.0, 0.0, 100.0, 100.0, [false; 4]);
        doc.extrusions.insert(model::Extrusion {
            sketch,
            faces: vec![model::ExtrudeFace::Polygon(lines.to_vec())],
            distance: 50.0,
            target: None,
            expression: String::new(),
            symmetric: false,
            name: None,
            taper: 0.0,
            taper_mode: crate::model::ExtrudeTaperMode::Distance,
            taper_expression: String::new(),
            edge_treatments: Vec::new(),
        });
        doc.bodies.insert(model::Body {
            source: model::BodySource::Extrusion(xkey(0)),
            material: None,
            name: None,
            shadow: false,
        });
        // A flattening projection: world (x, y) straight to screen pixels.
        let project = |w: Vec3| Some(egui::pos2(w.x, w.y));
        let origin = egui::pos2(50.0, 50.0); // mid-face, far from every edge
        let center = egui::pos2(400.0, 300.0);
        let radius = 20.0;
        let zoom = 6.0;
        let view = |members: &[(PK, Vec3)]| {
            loupe_view(
                &doc,
                &project,
                members.iter().map(|(k, a)| (k, *a)),
                origin,
                center,
                radius,
                zoom,
            )
        };

        // The whole body: its edges are ~50 px from the cursor, which the 6× magnifier throws
        // 300 px clear of a 20 px disc — nothing to see, so the loupe frames the body.
        let (pivot, z) = view(&[(PK::Body(bkey(0)), Vec3::new(0.0, 0.0, 0.0))]);
        assert!(z < zoom, "the body loupe must zoom out, got {z}");
        assert!(
            (pivot - egui::pos2(50.0, 50.0)).length() < 1.0,
            "framed on the body's own centre, got {pivot:?}"
        );

        // A corner right under the cursor still lands in the disc, so the magnifier stands.
        assert_eq!(
            view(&[(PK::BodyVertex { body: bkey(0), position: Vec3::new(50.0, 50.0, 0.0) }, Vec3::ZERO)]),
            (origin, zoom)
        );
    }

    /// #949: the end-point-B candidate dots are colour-coded by the axis the turn to each one
    /// goes about, so a sphereful of them reads as groups instead of one indistinguishable blue.
    #[test]
    fn rotation_axis_colours_pick_the_nearest_world_axis() {
        assert_eq!(rotation_axis_color(Vec3::X), col::X_AXIS);
        assert_eq!(rotation_axis_color(-Vec3::X), col::X_AXIS, "sign doesn't matter");
        assert_eq!(rotation_axis_color(Vec3::Y), col::Y_AXIS);
        assert_eq!(rotation_axis_color(Vec3::Z), col::Z_AXIS);
        // Mostly-Z with a lean is still Z.
        assert_eq!(
            rotation_axis_color(Vec3::new(0.3, -0.2, 0.9).normalize()),
            col::Z_AXIS
        );
    }

    /// #948: hovering a new end point B previews the move a click there would actually make,
    /// so a C pair that's already set stays in the probe — dropping it showed a pose without
    /// the spin, which taking end B never produces.
    #[test]
    fn end_b_hover_preview_keeps_the_c_pair() {
        let point = |body| model::MovePointRef::Vertex { body, p: [0; 3] };
        let cm = actions::CreatingMove {
            targets: vec![bkey(0)],
            translate_mode: model::MoveTranslateMode::PointSnap,
            start_point_a: Some(point(bkey(0))),
            end_point_a: Some(point(bkey(1))),
            start_point_b: Some(point(bkey(0))),
            end_point_b: Some(point(bkey(1))),
            start_point_c: Some(point(bkey(0))),
            end_point_c: Some(point(bkey(1))),
            ..Default::default()
        };
        let hovered = model::MovePointRef::OnEdge { body: bkey(1), p: [1, 2, 3] };

        let probe = move_hover_probe(&cm, MoveFocus::EndPointB, hovered);
        assert_eq!(probe.end_point_b, Some(hovered), "the hover fills end B");
        assert_eq!(probe.start_point_c, cm.start_point_c, "start C rides along");
        assert_eq!(probe.end_point_c, cm.end_point_c, "and so does end C");

        // The C picker's own hover fills C and leaves B alone.
        let probe = move_hover_probe(&cm, MoveFocus::EndPointC, hovered);
        assert_eq!(probe.end_point_c, Some(hovered));
        assert_eq!(probe.end_point_b, cm.end_point_b);
    }

    /// #659: with a Move point picker focused, the viewport hovers body corners and edges —
    /// what a click would take — instead of the whole body.
    #[test]
    fn move_point_pick_hovers_corners_and_edges() {
        use super::gpu_viewport;
        use super::resolve_viewport_hover_highlight;
        use crate::hierarchy::SceneElement;

        let mut doc = crate::model::Document::default();
        let mesh = doc.imported_meshes.insert(crate::model::ImportedMesh {
            triangles: vec![[
                glam::Vec3::new(-20.0, -20.0, 0.0),
                glam::Vec3::new(20.0, -20.0, 0.0),
                glam::Vec3::new(0.0, 20.0, 0.0),
            ]],
            source_name: "tri".to_string(),
                    step_bytes: None,
        });
        doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Imported(mesh),
            material: None,
            name: None,
            shadow: false,
        });

        let cam = crate::camera::Camera::default();
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        let hover = |cursor: egui::Pos2, pick: MovePickHover| {
            // With the Bodies picker armed the hover comes from the picker itself (#958), so
            // the walk needs the tool's picker rather than an empty list.
            let pickers = test_pickers(
                crate::element_picker::ElementFilter::kind(
                    crate::element_picker::ElementKind::Body,
                ),
                context::PickerTarget::MoveTargets,
                crate::element_picker::PickLimit::Infinite,
            );
            resolve_viewport_hover_highlight(
                false,
                crate::actions::Tool::Move,
                None,
                pick,
                false,
                false,
                false,
                false,
                Some(cursor),
                &cam,
                viewport,
                &vp,
                &doc,
                &project,
                None,
                &pickers,
            )
        };

        let corner = project(glam::Vec3::new(20.0, -20.0, 0.0)).unwrap();
        let on_corner = hover(corner, MovePickHover::Point);
        assert!(
            matches!(
                on_corner,
                Some(gpu_viewport::ViewportHoverHighlight::PickTarget(
                    crate::construction::PickTargetKind::BodyVertex { body, .. }
                )) if body == bkey(0)
            ),
            "a corner hovers while picking a point, got {on_corner:?}"
        );
        let edge_mid = project(glam::Vec3::new(0.0, -20.0, 0.0)).unwrap();
        let on_edge = hover(edge_mid, MovePickHover::Point);
        // Hovering an edge highlights the candidate POINT — its midpoint — not the whole
        // edge (#739).
        match on_edge {
            Some(gpu_viewport::ViewportHoverHighlight::PickTarget(
                crate::construction::PickTargetKind::BodyVertex { body, position },
            )) if body == bkey(0) => {
                assert!(
                    (position - glam::Vec3::new(0.0, -20.0, 0.0)).length() < 1e-3,
                    "the mark sits at the edge midpoint, got {position:?}"
                );
            }
            other => panic!("an edge hovers as its midpoint mark, got {other:?}"),
        }
        // Back on the Bodies picker, the whole body hovers again.
        let on_body = hover(edge_mid, MovePickHover::Bodies);
        assert!(
            matches!(
                on_body,
                Some(gpu_viewport::ViewportHoverHighlight::Element(SceneElement::Body(b))) if b == bkey(0)
            ),
            "the Bodies picker hovers whole bodies, got {on_body:?}"
        );
    }

    /// #643: which picks become a repeat axis. Sketch lines always; origin axes and body
    /// edges only while the axis picker is the focused one, so a body's edge still toggles
    /// that body once an axis is chosen.
    #[test]
    fn constraint_tool_hovers_origin_and_origin_axes() {
        use super::gpu_viewport;
        use super::resolve_viewport_hover_highlight;
        use crate::actions::SketchSession;
        use crate::hierarchy::SceneElement;
        use crate::model::{ConstraintLine, SketchAxis};

        // #394: with the Constraint tool, the sketch origin and the fixed origin axes are
        // constraint targets, so they must hover-highlight like they click-select (#241).
        let mut doc = crate::model::Document::default();
        let sketch = doc.add_sketch(crate::model::FaceId::ConstructionPlane(pkey(0)));
        // A line far from the origin so it never wins the pick.
        doc.lines
            .insert(crate::model::Line::from_local_endpoints(sketch, 30.0, 30.0, 60.0, 30.0));

        let cam = crate::camera::Camera::default();
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        let resolve = |cursor: egui::Pos2| {
            resolve_viewport_hover_highlight(
                false,
                crate::actions::Tool::Constraint,
                Some(SketchSession { sketch }),
                MovePickHover::Bodies,
                false,
                false,
                false,
                false,
                Some(cursor),
                &cam,
                viewport,
                &vp,
                &doc,
                &project,
                None,
                &[],
            )
        };

        let over_origin = project(glam::Vec3::ZERO).expect("origin projects");
        let hover = resolve(over_origin);
        assert!(
            matches!(
                hover,
                Some(gpu_viewport::ViewportHoverHighlight::Element(SceneElement::Origin))
            ),
            "hovering the origin should highlight it, got {hover:?}"
        );

        let over_x_axis = project(glam::Vec3::new(15.0, 0.0, 0.0)).expect("axis projects");
        let hover = resolve(over_x_axis);
        assert!(
            matches!(
                &hover,
                Some(gpu_viewport::ViewportHoverHighlight::Element(SceneElement::FaceEdge(
                    ConstraintLine::OriginAxis(SketchAxis::X)
                )))
            ),
            "hovering the X origin axis should highlight it, got {hover:?}"
        );
    }

    #[test]
    fn dimension_tool_hovers_a_dimensionable_line() {
        use super::gpu_viewport;
        use super::resolve_viewport_hover_highlight;
        use crate::actions::SketchSession;
        use crate::construction::PickTargetKind;

        // A sketch on the ground plane with one line near the origin.
        let mut doc = crate::model::Document::default();
        let sketch = doc.add_sketch(crate::model::FaceId::ConstructionPlane(pkey(0)));
        doc.lines
            .insert(crate::model::Line::from_local_endpoints(sketch, -20.0, 0.0, 20.0, 0.0));

        let cam = crate::camera::Camera::default();
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        // Aim the cursor at the line's midpoint on screen.
        let mid = project(glam::Vec3::ZERO).expect("origin projects into the viewport");

        let hover = resolve_viewport_hover_highlight(
            false,
            crate::actions::Tool::Dimension,
            Some(SketchSession { sketch }),
            MovePickHover::Bodies,
            false,
            false,
            false,
            false,
            Some(mid),
            &cam,
            viewport,
            &vp,
            &doc,
            &project,
            None,
            &[],
        );
        assert!(
            matches!(
                hover,
                Some(gpu_viewport::ViewportHoverHighlight::PickTarget(
                    PickTargetKind::Line(l)
                )) if l == lkey(0)
            ),
            "hovering a line with the Dimension tool should highlight it, got {hover:?}"
        );

        // #800: a **point** of that sketch highlights too — a dimension is often between two
        // different kinds of thing, and the click path has always accepted it.
        let end = project(glam::Vec3::new(20.0, 0.0, 0.0)).expect("the line's end projects");
        let hover = resolve_viewport_hover_highlight(
            false,
            crate::actions::Tool::Dimension,
            Some(SketchSession { sketch }),
            MovePickHover::Bodies,
            false,
            false,
            false,
            false,
            Some(end),
            &cam,
            viewport,
            &vp,
            &doc,
            &project,
            None,
            &[],
        );
        assert!(
            matches!(
                hover,
                Some(gpu_viewport::ViewportHoverHighlight::PickTarget(
                    PickTargetKind::Point(_)
                ))
            ),
            "hovering a sketch point with the Dimension tool should highlight it, got {hover:?}"
        );
    }

    /// #541: while the Mirror tool is active in a sketch, the line under the cursor
    /// hover-highlights (it's what a click would pick — the axis or a shape to reflect).
    #[test]
    fn mirror_tool_hovers_a_line_in_a_sketch() {
        use super::gpu_viewport;
        use super::resolve_viewport_hover_highlight;
        use crate::actions::SketchSession;

        let mut doc = crate::model::Document::default();
        let sketch = doc.add_sketch(crate::model::FaceId::ConstructionPlane(pkey(0)));
        doc.lines
            .insert(crate::model::Line::from_local_endpoints(sketch, -20.0, 0.0, 20.0, 0.0));

        let cam = crate::camera::Camera::default();
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let vp = cam.view_proj(viewport);
        let project = |w: glam::Vec3| cam.project(w, viewport, &vp);
        let mid = project(glam::Vec3::ZERO).expect("origin projects into the viewport");

        // The tool's own picker decides now (#958): the mirror line takes a line, scoped to
        // the open sketch by a rule rather than by an arm that repeats `element_in_sketch`.
        let pickers = test_pickers(
            crate::element_picker::ElementFilter::kind(crate::element_picker::ElementKind::Line)
                .rule(crate::element_picker::PickRule::InSketch(sketch)),
            context::PickerTarget::SketchMirrorLine,
            crate::element_picker::PickLimit::Finite(1),
        );
        let hover = resolve_viewport_hover_highlight(
            false,
            crate::actions::Tool::Mirror,
            Some(SketchSession { sketch }),
            MovePickHover::Bodies,
            false,
            false,
            false,
            false,
            Some(mid),
            &cam,
            viewport,
            &vp,
            &doc,
            &project,
            None,
            &pickers,
        );
        assert!(
            matches!(
                hover,
                Some(gpu_viewport::ViewportHoverHighlight::Element(
                    crate::hierarchy::SceneElement::Line(l)
                )) if l == lkey(0)
            ),
            "hovering a line with the Mirror tool should highlight it, got {hover:?}"
        );
    }

